import json

def build_addendum(E,table,img):
    a=json.loads((E/'results/regression_state_analysis.json').read_text())
    counts=lambda values:'、'.join(map(str,values))
    rows=[]
    for r in a['held_strata']:
        name={'red':'红块','blue':'蓝块','pink':'粉块'}.get(r['group'],r['group'])
        rows.append([name,r['positive_records'],r['roots'],counts(r['old_FN'])+' → '+counts(r['new_FN'])])
    parts=['<h3>退步集中在哪些实际状态</h3><p>以下只重新统计已经保存的预测和观测，没有再次运行模型。按抽屉状态和物体颜色分层后，held漏判主要集中于抽屉关闭的16个正例（仅2根）。颜色分层与抽屉分层是同一批99个正例的两种视角，不能把各行相加。</p>',table(['旧D真实held子集','正例分母','根数','FN：补前 → 补后（种子0、1、2）'],rows)]
    rows=[]
    for r in a['held_regression_states']:
        pix=r['visible_pixels_four_frames'];state=r['episode_id']+'，'+{'red':'红块','pink':'粉块'}[r['object']]
        rows.append([state,'关闭' if r['drawer']=='closed' else '打开',counts(r['newly_lost_records_by_seed']),f"{r['gripper_width_mm']:.2f} / {r['object_to_tcp_mm_evaluation_only']:.2f}",f"{min(pix['static'])}–{max(pix['static'])} / {min(pix['gripper'])}–{max(pix['gripper'])}"])
    parts += [table(['轨迹与目标','抽屉','新增漏判记录：种子0、1、2','夹爪开度 / 物体距TCP（mm）','四帧可见像素范围：静态 / 夹爪'],rows),
      '<p>全部新增held漏判只涉及上述三组已抬起的物体。前后标签相同且有效，关闭夹爪指令下实际开度约40 mm，物体中心距TCP约4–6 mm。红块和关抽屉粉块各有三个相邻边界，它们的末帧双相机RGB哈希完全相同，机器人观测也相同；因此7条漏判记录不是7次独立的抓取失败。开抽屉粉块对种子0是原有错误，对种子1、2才是新增错误。</p>',
      img(E/'figures/regression_states.png'),
      '<p class="caption">图中列出全部三组退步状态，每行展示同一输入历史的末帧；左为静态相机，中为夹爪相机，右为三个种子的前后概率及测量。画面红、蓝、粉是物体实际颜色；没有用颜色编码模型好坏。距离来自既有评估记录，仅用于诊断，没有输入模型，也没有用作筛选checkpoint。</p>',
      '<p><b>遮挡证据的边界：</b>三组状态在四帧、双相机中均有目标像素，且目标像素未触及原生图像边缘，因此不存在完全不可见或图像边缘裁掉目标的情况。图上仍可见手指覆盖局部物体；可见像素数和ROI掩码占用率不能换算为完整物体的遮挡百分比，不能据此排除局部遮挡、抓握姿态或背景组合的影响。当前没有单项遮挡替换实验，不能把遮挡说成已证实原因。</p>',
      '<p>新增训练的12个真实held窗口，物体距TCP为2.76–9.00 mm，开度40.24–40.31 mm。上述三组退步状态的距离均落在这个范围；开抽屉粉块的开度40.51 mm略超出该范围，但其余两组约40.25 mm。因此“夹爪离物体太远”不能解释这些held漏判，单凭上述两个物理量也不能证明视觉分布相同。新增11个闭合空夹爪靠近负例的目标距TCP约59.89–64.62 mm、开度约0 mm，覆盖的是另一种接近外观。</p>']
    parts += ['<h3>配比与分布：哪些关系可以直接证明</h3>',table(['量','旧训练','本轮增加或混合后','可以得出的结论'],[
       ['窗口数','900','新增73，共973；自然900:73抽样','未做困难样本过采样；完整预算旧样本曝光约减少7.5%。'],
       ['held监督事实','276正 / 2424负','新增12正 / 61负；合计288正 / 2485负','正例比例10.22% → 10.39%，不是整体负例占比上升。'],
       ['补采监督范围','每旧窗口7个有效事实','每新窗口2个：目标held与open；in为0','补采占7.50%窗口，约2.27%有效监督事实曝光。该比例不是测得的梯度贡献。'],
       ['补采抽屉标签','旧分布保持','38打开 / 35关闭；12个held正例中开、关各6','补采确实包含held且抽屉关闭，仍没有保住全部旧同类状态。'],
       ['开发集选择','旧实验使用原C','本轮只用新增37窗口 / 6根','不是相同开发分布；主结果包含选模影响，不能全归因于数据。']]),
       '<p><b>事实：</b>每种子完整运行1500次更新、90,000次窗口呈现，与旧训练相同。但等窗口预算不等于等监督事实数：旧训练约630,000次有效事实呈现，本轮为596,215–596,240次，约少5.36%；补采每窗口仅监督两个事实。其中补采窗口呈现分别为6752、6757、6753次，约7.50%。结构、损失形式、AdamW设置、随机种子集合及冻结视觉不变，但训练样本池和开发分布变了。原始错误统一按0.5计算，UNKNOWN另报。主模型由开发集选到第300、150、1500步；固定1500步对照仍有旧D held漏判4/99和近距离误报2/2，说明提前选中checkpoint不能独自解释全部退步。两个分布上表现的变化是观察事实；本轮未隔离“某一批负例”“替换旧样本曝光”“共享表示”各自的因果效应。</p>',
       '<p><b>对in误报的直接证据：</b>种子2的4次新误报全部来自关抽屉测试根，共4/19；开抽屉测试为0/19。具体是红、粉各一次张开夹爪靠近，粉块一次双侧接触但仍受桌面支撑，红块一次远离且闭合空夹爪。四例都未held且有2–4个外部支撑接触；并不只发生在靠近或夹爪闭合一种姿态上。三个错误P(True)&gt;0.998，另一个约0.518。</p>',
       '<p><b>尚未证实的解释：</b>held与in共享对象编码器和历史表示，新增样本更新这些表示但没有in监督，这与in在新状态上漂移相容；只按新增六根开发集选模，也可能偏向新分布。上述解释有结构与数据依据，但没有独立消融确认，不能写成唯一原因。更不能用“负样本变多”概括全部退步，因为监督类别比例并不支持这个简单说法。</p>',
       '<h3>模型保留建议</h3><p><b>保留旧冻结模型作为当前可复现的对照基线；新增模型仅保留为候选，不替换基线。</b>这是为了保留已知、可追溯的比较起点，不代表旧模型已可靠：它仍有抽屉误报与近距离held误报。新模型的定向改善值得保留，但旧held召回退步、跨种子不一致及in新误报尚未解决；本轮证据不足以将它接入世界模型或LTL闭环。全部旧、新checkpoint均保留，没有按测试结果挑选“最好种子”。</p>']
    return ''.join(parts)
